pub fn unexpected(self: *Lexer) !void {
            const found = finder: {
            self.start = @min(self.start, self.end);
            if ((self.start == self.source.contents.len)) {
                break :finder "end of file";
            } else {
                break :finder self.raw();
            }
};
            _ = try self.addRangeError(self.range(), "Unexpected {s}", .{ found });
    }

pub fn expectedString(self: *Lexer, text: []const u8) !void {
            const found = finder: {
            if ((self.source.contents.len != self.start)) {
                break :finder self.raw();
            } else {
                break :finder "end of file";
            }
};
            _ = try self.addRangeError(self.range(), "Expected {s} but found {s}", .{ text, found });
    }

pub fn range(self: Lexer) logger.Range {
            return logger.Range{ .loc = logger.usize2Loc(self.start), .len = std.math.lossyCast(i32, (self.end - self.start)) };
    }

pub fn init(self: *Lexer, log: *logger.Log, source: logger.Source, allocator: std.mem.Allocator, redact_logs: bool) Lexer!void {
        _ = &self;
            var lex = Lexer{ .log = log, .source = source, .prev_error_loc = logger.Loc.Empty, .allocator = allocator, .should_redact_logs = redact_logs };
            _ = &lex;
            _ = lex.step();
