    }

pub inline fn toString(self: *Lexer, loc_: logger.Loc) js_ast.Expr {
            if (self.string_literal_is_ascii) {
                return js_ast.Expr.init(js_ast.E.String, js_ast.E.String{ .data = self.string_literal_slice }, loc_);
            }
            return js_ast.Expr.init(js_ast.E.String, .{ .data = self.string_literal_slice }, loc_);
    }

pub fn raw(self: Lexer) []const u8 {
            return self.source.contents[self.start..self.end];
    }
